import { uiActions } from './ui-slice';

export const fetchCartData = () => {
    return dispatch => {
        const fetchData = async () => {
            const response = await fetch('https://react-http-1c2b1-default-rtdb.firebaseio.com/cart.json');
        }
    }
}

export const sendCartData = (cart) => {
    return async (dispatch) => {
        dispatch(
            uiActions.showNotification({
                status: 'pending',
                title: 'Sending...',
                message: 'Sending cart data!',
            })
        );

        const sendRequest = async () => {
            const response = await fetch(
              'https://react-http-1c2b1-default-rtdb.firebaseio.com/cart.json', 
              { 
                method: 'PUT', 
                bpdy: JSON.stringify(cart), 
              }
            );
        
            if (!response.ok) {
              throw new Error('Sending cart data failed.')
            }
        };
        try {
            await sendRequest();

            dispatch(
                uiActions.showNotification({
                    status: 'Success',
                    title: 'Success!',
                    message: 'Sent cart data successfuly!',
                })
            );
        } catch (error) {
            dispatch(
                uiActions.showNotification({
                    status: 'error',
                    title: 'error!',
                    message: 'Sending cart data failed!',
                })
            );
        }           
      
    };
};
